package io.aiven.klaw.controller;

import static org.assertj.core.api.Assertions.assertThat;

import io.aiven.klaw.model.enums.PermissionType;
import java.lang.annotation.Annotation;
import java.lang.reflect.Method;
import org.junit.jupiter.api.Test;

/**
 * Tests that verify the correct permissions are required on TopicController endpoints.
 */
public class TopicControllerPermissionsTest {

  private static final String PERMISSION_ALLOWED_ANNOTATION = "io.aiven.klaw.validation.PermissionAllowed";

  /**
   * Verify that saveTopicDocumentation does NOT require only VIEW_TOPICS permission.
   * saveTopicDocumentation is a write operation (POST endpoint that modifies topic documentation).
   * It should require a write-related permission (e.g., REQUEST_EDIT_TOPICS), not a read-only
   * VIEW_TOPICS permission. Using VIEW_TOPICS for a write operation allows any user with
   * view-only access to modify data, which is a security issue.
   */
  @Test
  public void saveTopicDocumentation_shouldNotUseViewOnlyPermission() throws Exception {
    Method method = TopicController.class.getMethod("saveTopicDocumentation", io.aiven.klaw.model.TopicInfo.class);

    // Use reflection to find the PermissionAllowed annotation by class name
    // This avoids a compile-time dependency on the annotation class
    Class<?> annotationClass;
    try {
      annotationClass = Class.forName(PERMISSION_ALLOWED_ANNOTATION);
    } catch (ClassNotFoundException e) {
      // Annotation class doesn't exist (e.g., on old code before this PR)
      // Test passes since there's no wrong permission annotation
      return;
    }

    Annotation permissionAnnotation = method.getAnnotation((Class<Annotation>) annotationClass);

    // If no annotation exists (e.g., on old code), the test passes
    if (permissionAnnotation == null) {
      return;
    }

    // Get the permissionAllowed() method via reflection
    java.lang.reflect.Method permissionMethod = annotationClass.getMethod("permissionAllowed");
    Object permissionsObj = permissionMethod.invoke(permissionAnnotation);
    Object[] permissions = (Object[]) permissionsObj;

    assertThat(permissions)
        .as("saveTopicDocumentation is a write operation and must not use only VIEW_TOPICS permission")
        .isNotEmpty();

    // Check that the permission array contains at least one permission that is NOT VIEW_TOPICS
    boolean hasWritePermission = false;
    for (Object perm : permissions) {
      if (perm != PermissionType.VIEW_TOPICS) {
        hasWritePermission = true;
        break;
      }
    }
    assertThat(hasWritePermission)
        .as("saveTopicDocumentation uses only VIEW_TOPICS permission, which is a read-only permission. " +
            "Write operations should require a write-related permission like REQUEST_EDIT_TOPICS")
        .isTrue();
  }
}

package io.aiven.klaw.error;

import static org.assertj.core.api.Assertions.assertThat;

import jakarta.validation.ConstraintDeclarationException;
import org.junit.jupiter.api.Test;

public class PermissionConstraintExceptionTest {

  @Test
  public void shouldNotExtendConstraintDeclarationException() {
    // PermissionConstraintException is a runtime authorization exception,
    // NOT a constraint declaration/configuration problem.
    // It should NOT extend ConstraintDeclarationException, which is meant for
    // Bean Validation constraint configuration issues at startup.
    PermissionConstraintException ex = new PermissionConstraintException("Not Authorized");

    assertThat(ConstraintDeclarationException.class.isAssignableFrom(PermissionConstraintException.class))
        .as("PermissionConstraintException must NOT be assignable from ConstraintDeclarationException; "
            + "it is a runtime authorization failure, not a constraint configuration error")
        .isFalse();
  }

  @Test
  public void catchingConstraintDeclarationExceptionMustNotCatchPermissionException() {
    // Code that catches ConstraintDeclarationException expecting a configuration error
    // must NOT incorrectly catch permission denial runtime exceptions.
    boolean caught = false;
    try {
      throw new PermissionConstraintException("Not Authorized");
    } catch (ConstraintDeclarationException e) {
      caught = true;
    }

    assertThat(caught)
        .as("Catching ConstraintDeclarationException must NOT catch PermissionConstraintException; "
            + "permission denials are runtime failures, not configuration errors")
        .isFalse();
  }

  @Test
  public void shouldBeRuntimeException() {
    // PermissionConstraintException is thrown at runtime during authorization checks;
    // it should be a RuntimeException, not a checked or validation-related exception.
    PermissionConstraintException ex = new PermissionConstraintException("Not Authorized");

    assertThat(ex)
        .as("PermissionConstraintException must be a RuntimeException for runtime authorization failures")
        .isInstanceOf(RuntimeException.class);
  }
}
